import math
def compute_RBF(task_i, t):
    return math.ceil(t / task_i.T_i) * task_i.C_i

def compute_TS(task_set, i):
    def P(k, t):
        if k == 0:
            return {t}
        points = P(k-1, t)
        new_points = set()
        for p in points:
            new_points.add(math.floor(p / task_set[k-1].T_i) * task_set[k-1].T_i)
        return points.union(new_points)

    return P(i-1, task_set[i-1].D_i)

def compute_blocking(task_set, i, q_values):
    # q_values is a list of NP region lengths for each task
    lower_priority_qs = q_values[i:] # tasks from i+1 to n
    if not lower_priority_qs:
        return 0
    return max(lower_priority_qs)

def compute_beta_i(task_set, i):
    testing_set = compute_TS(task_set, i)
    max_slack = -float('inf')
    for t in testing_set:
        slack = t - compute_W_i_t(task_set, i, t)
        if slack > max_slack:
            max_slack = slack
    return max_slack

def is_schedulable_with_NP(task_set, q_values):
    for i in range(len(task_set)):
        B_i = compute_blocking(task_set, i, q_values)
        ts = compute_TS(task_set, i+1)
        feasible = False
        for t in ts:
            if compute_W_i_t(task_set, i+1, t) + B_i <= t:
                feasible = True
                break
        if not feasible:
            return False
    return True

def compute_all_Q(task_set):
    n = len(task_set)
    Q = [0] * n
    beta = [0] * n

    for i in range(n):
        beta[i] = compute_beta_i(task_set, i+1)

    Q[0] = float('inf')
    for i in range(1, n):
        Q[i] = min(Q[i-1], beta[i-1])
    return Q

def compute_beta_approx_D(task_set, i):
    D_i = task_set[i-1].D_i
    slack = D_i - compute_W_i_t(task_set, i, D_i)
    return max(0, slack)

def compute_beta_approx_LL(task_set, i):
    u_lub = i * (2**(1/i) - 1)
    sum_u = sum(t.C_i / t.T_i for t in task_set[:i])
    return max(0, task_set[i-1].T_i * (u_lub - sum_u))
